  {"question": "Which two organizations published frameworks for frontier AI risk management in 2025?", "answer": "Meta and Shanghai Artificial Intelligence Laboratory & Concordia AI both published frameworks for frontier AI risk management in 2025.", "evidence": [{"page": 63, "quote": "- Meta. (2025). Frontier AI Framework. https://ai.meta.com/static-resource/meta-frontier-aiframework/?utm_source=newsroom&utm_medium=web&utm_content=Frontier_AI_Framew ork_PDF&utm_campaign=Our_Approach_to_Frontier_AI_blog"}, {"page": 70, "quote": "- Shanghai Artificial Intelligence Laboratory, & Concordia AI. (2025). Frontier AI Risk Management Framework. https://research.ai45.shlab.org.cn/safework-f1-framework.pdf"}]},
  {"question": "What is the purpose of the MIT AI Incident Tracker as described in the AI Index Report 2025?", "answer": "The MIT AI Incident Tracker catalogs AI incidents to prevent repeated real world failures, as referenced in the AI Index Report 2025.", "evidence": [{"page": 63, "quote": "- MIT. (n.d.-a). MIT AI Incident Tracker. Retrieved 22 February 2026, from https://airisk.mit.edu/aiincident-tracker"}, {"page": 62, "quote": "- Maslej, N., Fattorini, L., Perrault, R., Gil, Y., Parli, V., Kariuki, N., Capstick, E., Reuel, A., Brynjolfsson, E., Etchemendy, J., Ligett, K., Lyons, T., Manyika, J., Niebles, J. C., Shoham, Y., Wald, R., Walsh, T., Hamrah, A., Santarlasci, L., … Oak, S. (2025). Artificial Intelligence Index Report 2025 (arXiv:2504.07139). arXiv. https://doi.org/10.48550/arXiv.2504.07139"}]},
  {"question": "What does the abbreviation 'SAPs' stand for in the ONR Safety Assessment Principles?", "answer": "SAPs stands for Safety Assessment Principles in the ONR Safety Assessment Principles.", "evidence": [{"page": 66, "quote": "ONR. (2020). Safety Assessment Principles (SAPs) [Text/html]. https://www.brightwire.net. (https://www.onr.org.uk/). https://www.onr.org.uk/publications/regulatoryguidance/regulatory-assessment-and-permissioning/safety-assessment-principles-saps"}]},
  {"question": "Which publication discusses the ESA's approach to safety risk assessment and management?", "answer": "Preyssl, C. (1995) discusses the ESA's approach to safety risk assessment and management.", "evidence": [{"page": 68, "quote": "- Preyssl, C. (1995). Safety risk assessment and management-The ESA approach. Reliability Engineering & System Safety, Space System Applications of Risk Assessment, 49(3), 303-309. https://doi.org/10.1016/0951-8320(95)00047-6"}]},
  {"question": "Which organization released a taxonomy for AI risk mitigation in late 2025?", "answer": "MIT released the AI Risk Mitigation Taxonomy in late 2025.", "evidence": [{"page": 63, "quote": "- MIT. (n.d.-b). The AI Risk Mitigation Taxonomy. Retrieved 22 February 2026, from https://airisk.mit.edu/ai-risk-mitigations"}]},
  {"question": "Who authored the framework for assurance audits of algorithmic systems presented at the 2024 ACM Conference on Fairness, Accountability, and Transparency?", "answer": "Lam, K., Lange, B., Blili-Hamelin, B., Davidovic, J., Brown, S., & Hasan, A. authored the framework for assurance audits of algorithmic systems.", "evidence": [{"page": 59, "quote": "- Lam, K., Lange, B., Blili-Hamelin, B., Davidovic, J., Brown, S., & Hasan, A. (2024). A Framework for Assurance Audits of Algorithmic Systems. The 2024 ACM Conference on Fairness, Accountability, and Transparency, 1078-1092. https://doi.org/10.1145/3630106.3658957"}]}
]}
